function cleanLookupTerm(value=''){return(value.match(/[A-Za-z][A-Za-z'-]*/)||[])[0]?.toLowerCase()||''}
function lookupMatches(term){const q=cleanLookupTerm(term);if(!q)return[];const exact=deck.filter(w=>w.word.toLowerCase()===q),prefix=deck.filter(w=>w.word.toLowerCase().startsWith(q)&&w.word.toLowerCase()!==q),related=deck.filter(w=>w.word.toLowerCase().includes(q)&&!w.word.toLowerCase().startsWith(q));return[...exact,...prefix,...related].slice(0,10)}
