function runWordLookup(){const raw=$('wordLookupInput').value.trim(),term=cleanLookupTerm(raw),results=lookupMatches(term),box=$('wordLookupResults');if(!term){box.innerHTML='<div class="lookup-empty">输入单词，或先在文章中选中一个词。</div>';return}lookupHistory=[term,...lookupHistory.filter(x=>x!==term)].slice(0,8);write('tri-lookup-history',lookupHistory);renderLookupHistory();$('lookupExternal').href=`https://www.youdao.com/result?word=${encodeURIComponent(term)}&lang=en`;$('lookupCambridge').href=`https://dictionary.cambridge.org/dictionary/english/${encodeURIComponent(term)}`;box.innerHTML=results.length?results.map((w,i)=>`<article class="lookup-result ${i===0&&w.word.toLowerCase()===term?'exact':''}"><div><span>${escapeHtml(w.pos||w.tags?.split(' ').filter(Boolean).slice(0,2).join(' · ')||'EXAM WORD')}</span><h3>${escapeHtml(w.word)}</h3><small>${escapeHtml(w.phonetic||'')}</small></div><p>${escapeHtml(w.meaning||'暂无中文释义')}</p>${w.definition?`<em>${escapeHtml(w.definition)}</em>`:''}<button class="soft" data-review-word="${escapeAttr(w.word)}">加入待复习</button></article>`).join(''):`<div class="lookup-empty"><b>本地 6000 词库暂未收录 “${escapeHtml(term)}”</b><span>可使用下方有道或 Cambridge 联网查询。</span></div>`;box.querySelectorAll('[data-review-word]').forEach(button=>button.onclick=()=>{const word=deck.find(w=>w.word.toLowerCase()===button.dataset.reviewWord.toLowerCase());if(!word)return;word.status='learning';word.due=dateKey();word.reps=word.reps||0;wordProgress[word.word.toLowerCase()]={status:word.status,due:word.due,reps:word.reps};write('tri-word-progress',wordProgress);renderEnglishStats();button.textContent='已加入 ✓';button.disabled=true;toast(`${word.word} 已加入待复习`)})}
