function catalogKind(name){const ext=name.split('.').pop().toLowerCase();if(['mp4','m4v','mov','webm','mkv','avi'].includes(ext))return'video';if(['pdf','doc','docx','ppt','pptx','txt','md'].includes(ext))return'note';return''}
function minutesFromName(name,kind){const m=name.match(/(?:\[|（|\()?\s*(\d{1,3})\s*(?:min|分钟)/i);return m?+m[1]:kind==='video'?45:20}
async function detectVideoMinutes(file){return new Promise(resolve=>{const estimated=minutesFromName(file.name,'video'),video=document.createElement('video'),url=URL.createObjectURL(file),finish=v=>{URL.revokeObjectURL(url);resolve(v)};const timer=setTimeout(()=>finish(estimated),3500);video.preload='metadata';video.onloadedmetadata=()=>{clearTimeout(timer);finish(Number.isFinite(video.duration)?Math.max(1,Math.round(video.duration/60)):estimated)};video.onerror=()=>{clearTimeout(timer);finish(estimated)};video.src=url})}
async function filesToCatalog(subject,files){const accepted=[];for(const file of files){const kind=catalogKind(file.name);if(!kind)continue;const path=file.webkitRelativePath||file._relativePath||file.name,id=uid(),minutes=kind==='video'?await detectVideoMinutes(file):20;accepted.push({id,subject,name:file.name,path,kind,minutes,size:file.size});sessionCourseFiles.set(id,file)}return accepted.sort((a,b)=>a.path.localeCompare(b.path,'zh-CN',{numeric:true}))}
async function scanDirectory(handle,prefix=''){let files=[];for await(const entry of handle.values()){const path=prefix?`${prefix}/${entry.name}`:entry.name;if(entry.kind==='directory')files.push(...await scanDirectory(entry,path));else{const file=await entry.getFile();file._relativePath=path;files.push(file)}}return files}
async function saveDirectoryHandle(subject,handle){const db=await openFileDb();await new Promise((resolve,reject)=>{const tx=db.transaction('handles','readwrite');tx.objectStore('handles').put({id:subject,handle});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close()}
async function getDirectoryHandle(subject){const db=await openFileDb(),row=await new Promise((resolve,reject)=>{const req=db.transaction('handles').objectStore('handles').get(subject);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});db.close();return row?.handle}
async function importCourseFiles(subject,files,handle=null){if(!files.length)return toast('目录中没有可识别的视频或讲义');toast('正在识别课程与视频时长…');courseCatalog[subject]=await filesToCatalog(subject,files);write('tri-course-catalog',courseCatalog);if(handle)try{await saveDirectoryHandle(subject,handle)}catch{}buildSmartSchedule(subject);renderCatalogSummary(subject);subject==='math'?renderMath():renderPolitics();toast(`已导入 ${courseCatalog[subject].length} 个课程文件`)}
function renderCatalogSummary(subject){const items=courseCatalog[subject]||[],videos=items.filter(x=>x.kind==='video'),notes=items.filter(x=>x.kind==='note'),minutes=videos.reduce((n,x)=>n+x.minutes,0);$(`${subject}CatalogSummary`).innerHTML=items.length?`已识别 <b>${videos.length}</b> 个视频、<b>${notes.length}</b> 份讲义<br>视频约 ${Math.floor(minutes/60)} 小时 ${minutes%60} 分钟 · 当前计划 ${Object.keys(smartSchedules[subject]||{}).length} 个学习日`:'尚未导入课程目录'}
function createCourseSchedule(items,start,minutes,weekdays,subject){const schedule={};let cursor=0,d=new Date(start+'T00:00:00'),guard=0;while(cursor<items.length&&guard<5000){const key=dateKey(d),constraints=dayConstraints(d),free=StudyPlanner.subtract(studyWindows(),constraints.busy).reduce((sum,slot)=>sum+slot.end-slot.start,0),reserve=subject==='math'?190:260,budget=Math.min(minutes,Math.max(0,free-reserve));if(weekdays.includes(d.getDay())&&!subjectPostponements[subject]?.[key]&&budget>0){const today=[];let used=0;while(cursor<items.length){const item=items[cursor],cost=item.minutes||20;if(used+cost>budget&&(today.length||cost<=minutes))break;today.push(item.id);used+=cost;cursor++}if(today.length)schedule[key]=today}d.setDate(d.getDate()+1);guard++}return{schedule,cursor,lastDate:dateKey(d)}}
function rebuildSmartSchedule(subject){const config=smartConfig[subject],items=courseCatalog[subject]||[],built=createCourseSchedule(items,config.start,config.minutes,config.weekdays,subject);smartSchedules[subject]=built.schedule;write('tri-smart-schedules',smartSchedules);return built}
function buildSmartSchedule(subject){
 const start=$(`${subject}PlanStart`)?.value||smartConfig[subject].start,minutes=+$(`${subject}DailyMinutes`)?.value||smartConfig[subject].minutes,box=document.querySelector(`[data-weekdays="${subject}"]`),weekdays=box?[...box.querySelectorAll('input:checked')].map(x=>+x.value):smartConfig[subject].weekdays;
 if(!weekdays.length)return toast('请至少选择一个学习日');smartConfig[subject]={start,minutes,weekdays};write('tri-smart-config',smartConfig);const items=courseCatalog[subject]||[],built=rebuildSmartSchedule(subject);renderCatalogSummary(subject);subject==='math'?renderMath():renderPolitics();toast(built.cursor<items.length?'部分课程超出当前预算，仍保留在目录；请提高预算或调整学习时段':'智能课程表已生成；顺延日会自动跳过')
}
function smartItemsFor(subject,key){const ids=smartSchedules[subject]?.[key]||[],items=courseCatalog[subject]||[];return ids.map(id=>items.find(x=>x.id===id)).filter(Boolean)}
function backlogFor(subject,key){const items=courseCatalog[subject]||[],scheduled=smartSchedules[subject]||{};return Object.keys(scheduled).filter(d=>d<key).sort().flatMap(d=>(scheduled[d]||[]).map(id=>items.find(x=>x.id===id))).filter(x=>x&&!courseProgress[x.id]).slice(0,2)}
async function openCourseFile(subject,item){try{let file=sessionCourseFiles.get(item.id);if(!file){const root=await getDirectoryHandle(subject);if(!root)throw 0;if(root.requestPermission&&await root.requestPermission({mode:'read'})!=='granted')throw 0;const parts=item.path.split('/');let dir=root;for(let i=0;i<parts.length-1;i++)dir=await dir.getDirectoryHandle(parts[i]);file=await(await dir.getFileHandle(parts.at(-1))).getFile()}const url=URL.createObjectURL(file);window.open(url,'_blank');setTimeout(()=>URL.revokeObjectURL(url),3600000)}catch{toast('请重新选择一次同步目录以恢复文件访问权限')}}
function renderImportedToday(subject){const key=dateKey(selectedPlanDate),box=$(`${subject}ImportedToday`);if(subjectPlanState(subject).postponed){box.innerHTML='<div class="deferred-course">今天已设为无学习日，网盘课程也已整体顺延。</div>';return}const today=smartItemsFor(subject,key),backlog=backlogFor(subject,key),all=[...backlog.map(x=>({...x,backlog:true})),...today.filter(x=>!backlog.some(b=>b.id===x.id))];if(!all.length){box.innerHTML=courseCatalog[subject]?.length?'<div class="empty">今天没有排入的网盘课程。</div>':'';return}const total=all.reduce((n,x)=>n+(x.minutes||20),0);box.innerHTML=`<div class="course-total">网盘课程 ${all.length} 项 · 预计 ${total} 分钟</div>`+all.map(x=>`<div class="imported-course ${courseProgress[x.id]?'done':''}"><b>${x.backlog?'待回收 · ':''}${escapeHtml(x.name)}</b><span>${x.kind==='video'?'视频':'讲义'} · ${x.minutes}分钟 · ${escapeHtml(x.path)}</span><button class="study-timer-launch" data-study-timer-key="${subject}-course-${escapeAttr(x.id)}" data-study-timer-label="${escapeAttr(`${SUBJECT_LABELS[subject]} · ${x.name}`)}">◷ 计时</button><button data-open-course="${x.id}">打开文件</button><button data-complete-course="${x.id}">${courseProgress[x.id]?'已完成 ✓':'标记完成'}</button></div>`).join('');box.querySelectorAll('[data-open-course]').forEach(b=>b.onclick=()=>openCourseFile(subject,(courseCatalog[subject]||[]).find(x=>x.id===b.dataset.openCourse)));box.querySelectorAll('[data-complete-course]').forEach(b=>b.onclick=()=>{courseProgress[b.dataset.completeCourse]=!courseProgress[b.dataset.completeCourse];write('tri-course-progress',courseProgress);renderImportedToday(subject)});bindStudyTimerButtons(box)}
