function fitnessInfoFor(date){const start=new Date(`${fitnessSettings.start}T00:00:00`),target=new Date(date);target.setHours(0,0,0,0);if(target<start)return{type:'before',muscle:null};const key=dateKey(target),weekly=fitnessSettings.weeklyRest.includes(target.getDay());if(weekly||fitnessRest[key])return{type:'rest',reason:weekly?'固定休息日':fitnessRest[key],muscle:null};let active=0,d=new Date(start);while(d<target){const k=dateKey(d);if(!fitnessSettings.weeklyRest.includes(d.getDay())&&!fitnessRest[k])active++;d.setDate(d.getDate()+1)}return{type:'workout',muscle:MUSCLES[active%MUSCLES.length]}}
function legacyExercise(line,muscle,index){let name=line.trim(),sets='',reps='',note='',match=name.match(/^(.+?)\s+(\d+)\s*[×xX]\s*(.+)$/);if(match){name=match[1];sets=match[2];reps=match[3]}else if((match=name.match(/^(.+?)\s+(\d+)\s*组$/))){name=match[1];sets=match[2]}else if((match=name.match(/^(.+?)\s+(\d+\s*(?:分钟|秒))$/))){name=match[1];reps=match[2]}return{id:`plan-${muscle}-${index}`,name,sets,reps,note}}
function ensureFitnessPlans(){fitnessSettings.exercisePlans=fitnessSettings.exercisePlans||{};MUSCLES.forEach(muscle=>{if(!Array.isArray(fitnessSettings.exercisePlans[muscle.id]))fitnessSettings.exercisePlans[muscle.id]=String(fitnessSettings.templates[muscle.id]||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map((line,index)=>legacyExercise(line,muscle.id,index));fitnessSettings.exercisePlans[muscle.id]=fitnessSettings.exercisePlans[muscle.id].map((exercise,index)=>({id:exercise.id||`plan-${muscle.id}-${index}`,name:String(exercise.name||'').trim(),sets:String(exercise.sets||''),reps:String(exercise.reps||''),note:String(exercise.note||'')})).filter(exercise=>exercise.name)})}
ensureFitnessPlans();
function renderFitnessWeekdays(){const box=$('fitnessWeekdays');box.innerHTML=DAY_ORDER.map(d=>`<label><input type="checkbox" value="${d}" ${fitnessSettings.weeklyRest.includes(d)?'checked':''}><span>${DAYS[d]}</span></label>`).join('')}
function fitnessExercises(muscle,key=dateKey(selectedPlanDate)){const rows=Object.prototype.hasOwnProperty.call(fitnessOverrides,key)?fitnessOverrides[key]:fitnessSettings.exercisePlans[muscle.id];return(Array.isArray(rows)?rows:[]).filter(exercise=>exercise?.name)}
function exerciseMeta(exercise){return[exercise.sets?`${exercise.sets} 组`:'',exercise.reps||'',exercise.note||''].filter(Boolean).join(' · ')}
function renderFitnessChecklist(info,key,log){const weekly=fitnessSettings.weeklyRest.includes(selectedPlanDate.getDay());if(info.type==='before'){$('fitnessMuscle').textContent='循环尚未开始';$('fitnessStatus').textContent=`训练循环从 ${fitnessSettings.start} 开始`;$('fitnessExerciseList').innerHTML='<div class="empty">可在右侧修改循环开始日期。</div>';return}if(info.type==='rest'){$('fitnessMuscle').textContent='恢复日';$('fitnessStatus').textContent=weekly?'固定休息星期；当天不推进五日循环。':info.reason==='postponed'?'训练已推迟，下一训练日继续当前部位。':'临时休息；后续部位自动顺延。';$('fitnessExerciseList').innerHTML='<div class="empty">散步、拉伸、正常饮食与睡眠即可。</div>';return}const exercises=fitnessExercises(info.muscle,key);$('fitnessMuscle').textContent=info.muscle.title;$('fitnessStatus').textContent=log.complete?'当天训练已完成 ✓':`${Object.prototype.hasOwnProperty.call(fitnessOverrides,key)?'今日使用单独项目；':'使用固定动作模板；'}完成后逐项打卡。`;$('fitnessExerciseList').innerHTML=exercises.length?exercises.map((exercise,index)=>{const done=log.checks.includes(exercise.id)||log.checks.includes(index);return`<div class="exercise-item ${done?'done':''}" data-exercise-id="${escapeAttr(exercise.id)}" data-exercise-index="${index}"><button aria-label="打卡 ${escapeAttr(exercise.name)}"></button><span><b>${escapeHtml(exercise.name)}</b>${exerciseMeta(exercise)?`<small>${escapeHtml(exerciseMeta(exercise))}</small>`:''}</span></div>`}).join(''):'<div class="empty">尚未填写动作，请在右侧自由添加训练项目。</div>';$('fitnessExerciseList').querySelectorAll('[data-exercise-id]').forEach(element=>element.onclick=()=>{const id=element.dataset.exerciseId,index=+element.dataset.exerciseIndex,current=fitnessLogs[key]||{checks:[],complete:false,note:''},done=current.checks.includes(id)||current.checks.includes(index);current.checks=current.checks.filter(item=>item!==id&&item!==index);if(!done)current.checks.push(id);fitnessLogs[key]=current;write('tri-fitness-logs',fitnessLogs);renderFitnessChecklist(info,key,current)})}
function collectExerciseEditor(){return[...$('exerciseEditorList').querySelectorAll('.exercise-editor-row')].map((row,index)=>({id:row.dataset.id||`custom-${Date.now()}-${index}`,name:row.querySelector('[data-field="name"]').value.trim(),sets:row.querySelector('[data-field="sets"]').value.trim(),reps:row.querySelector('[data-field="reps"]').value.trim(),note:row.querySelector('[data-field="note"]').value.trim()})).filter(exercise=>exercise.name)}
