 if(!$('analysisRange'))return;$('analysisWeightDate').value=$('analysisWeightDate').value||suggestedWeightDate();const end=new Date(selectedPlanDate);end.setHours(0,0,0,0);const start=new Date(end);start.setDate(start.getDate()-29);const startKey=dateKey(start),endKey=dateKey(end),energy=calculateEnergy(),proteinTarget=Math.round(nutritionProfile.weight*1.8);
 const mealDays=Object.entries(mealLogs).filter(([key,items])=>key>=startKey&&key<=endKey&&Array.isArray(items)&&items.length).map(([date,items])=>({date,cal:items.reduce((n,x)=>n+(+x.cal||0),0),protein:items.reduce((n,x)=>n+(+x.p||0),0)}));
 const weights=Object.entries(weightLogs).filter(([key,value])=>key>=startKey&&key<=endKey&&Number.isFinite(+value)).map(([date,value])=>({date,value:+value,x:(new Date(`${date}T00:00:00`)-start)/DAY_MS})).sort((a,b)=>a.date.localeCompare(b.date));
 const avg=(rows,field)=>rows.length?rows.reduce((n,x)=>n+(+x[field]||0),0)/rows.length:0,avgCal=avg(mealDays,'cal'),avgProtein=avg(mealDays,'protein'),adherent=mealDays.filter(x=>Math.abs(x.cal-energy.target)<=200).length;
