 syncPlanDates();$('profileSex').value=nutritionProfile.sex;$('profileAge').value=nutritionProfile.age;$('profileHeight').value=nutritionProfile.height;$('profileWeight').value=nutritionProfile.weight;$('activityFactor').value=nutritionProfile.activity;$('calorieDeficit').value=nutritionProfile.deficit;const energy=calculateEnergy(),key=dateKey(selectedPlanDate),meals=mealLogs[key]||[],sum=field=>meals.reduce((n,x)=>n+(+x[field]||0),0),cal=Math.round(sum('cal')),protein=sum('p'),carbs=sum('c'),fat=sum('f'),remaining=energy.target-cal;
