 $('expenseList').innerHTML=rows.length?`<div class="expense-list-head"><b>本月明细</b><span>${rows.length} 笔</span></div>`+rows.map(x=>`<div class="expense-row"><span class="expense-category">${escapeHtml(x.category)}</span><div><b>${escapeHtml(x.note||x.category)}</b><span>${x.date}</span></div><strong>−¥${yuan(x.amount)}</strong><button data-delete-expense="${x.id}" aria-label="删除这笔开支">×</button></div>`).join(''):'<div class="empty">保存第一笔开支后会显示在这里。</div>';document.querySelectorAll('[data-delete-expense]').forEach(b=>b.onclick=()=>{if(confirm('删除这笔开支吗？')){expenseLogs=expenseLogs.filter(x=>x.id!==b.dataset.deleteExpense);write('tri-expense-logs',expenseLogs);renderFinance();toast('开支已删除')}});
