$('settleFinance').onclick=()=>{const startText=$('settlementStart').value,endText=$('settlementEnd').value;if(!startText||!endText||startText>endText)return toast('请检查结算日期区间');const start=new Date(`${startText}T00:00:00`),end=new Date(`${endText}T00:00:00`);if((end-start)/DAY_MS>730)return toast('单次结算区间请控制在两年内');let allocated=0,days=0;for(let d=new Date(start);d<=end;d.setDate(d.getDate()+1)){const month=`${d.getFullYear()}-${pad(d.getMonth()+1)}`;allocated+=financeBudgetFor(month)/new Date(d.getFullYear(),d.getMonth()+1,0).getDate();days++}const spent=(Array.isArray(expenseLogs)?expenseLogs:[]).filter(x=>x.date>=startText&&x.date<=endText).reduce((n,x)=>n+(+x.amount||0),0),remaining=allocated-spent;$('settlementResult').innerHTML=`<div><span>${days} 天可用预算</span><b>¥${yuan(allocated)}</b></div><div><span>同期实际支出</span><b>−¥${yuan(spent)}</b></div><div class="${remaining<0?'negative':'positive'}"><span>${remaining<0?'超出预算':'假期前累计剩余'}</span><strong>${remaining<0?'−':'＋'}¥${yuan(Math.abs(remaining))}</strong></div>`};
