function studyTimerKey(base){return`${dateKey(selectedPlanDate)}::${base}`}
function studyTimerRecord(key,label='学习任务'){let state=studyTimers[key];if(!state||typeof state!=='object')state=studyTimers[key]={label,mode:'stopwatch',durationSeconds:1500,baseSeconds:0,running:false,startedAt:0};state.label=label||state.label||'学习任务';state.mode=state.mode==='countdown'?'countdown':'stopwatch';state.durationSeconds=Math.max(1,Math.min(359999,+state.durationSeconds||1500));state.baseSeconds=Math.max(0,+state.baseSeconds||0);state.running=!!state.running;state.startedAt=+state.startedAt||0;return state}
function studyTimerValue(state,now=Date.now()){if(!state)return 0;const delta=state.running&&state.startedAt?Math.max(0,Math.floor((now-state.startedAt)/1000)):0;return state.mode==='countdown'?Math.max(0,state.baseSeconds-delta):state.baseSeconds+delta}
function formatStudyTime(total){total=Math.max(0,Math.floor(total||0));const h=Math.floor(total/3600),m=Math.floor(total%3600/60),s=total%60;return`${pad(h)}:${pad(m)}:${pad(s)}`}
function saveStudyTimers(){write('tri-study-timers',studyTimers)}
function pauseStudyTimer(state){if(!state?.running)return;state.baseSeconds=studyTimerValue(state);state.running=false;state.startedAt=0}
function activeStudyTimer(){return activeStudyTimerKey?studyTimers[activeStudyTimerKey]:null}
function renderStudyTimerButtons(root=document){root.querySelectorAll?.('[data-study-timer-key]').forEach(button=>{const state=studyTimers[studyTimerKey(button.dataset.studyTimerKey)],value=state?studyTimerValue(state):null;let badge=button.querySelector('.timer-launch-value');if(!badge){badge=document.createElement('span');badge.className='timer-launch-value';button.appendChild(badge)}badge.textContent=value===null?'':formatStudyTime(value);button.classList.toggle('running',!!state?.running);button.title=state?`${state.label} · ${state.mode==='countdown'?'倒计时':'正计时'} ${formatStudyTime(value)}`:'打开独立计时器'})}
function renderActiveStudyTimer(){const state=activeStudyTimer(),has=!!state,value=studyTimerValue(state);$('studyTimerTitle').textContent=has?state.label:'选择一个学习小任务';$('studyTimerHint').textContent=has?`${activeStudyTimerKey.split('::')[0]} · ${state.mode==='countdown'?'自定义倒计时':'从 0 开始正计时'} · 自动保存在本机`:'各任务独立保存，可正计时或自定义倒计时。';$('studyTimerDisplay').textContent=formatStudyTime(value);document.querySelectorAll('[data-study-timer-mode]').forEach(button=>button.classList.toggle('active',has&&button.dataset.studyTimerMode===state.mode));$('studyTimerCustom').classList.toggle('visible',has&&state.mode==='countdown');const timerInputs=[$('studyTimerHours'),$('studyTimerMinutes'),$('studyTimerSeconds')];if(has&&!timerInputs.includes(document.activeElement)){const duration=state.durationSeconds;$('studyTimerHours').value=Math.floor(duration/3600);$('studyTimerMinutes').value=Math.floor(duration%3600/60);$('studyTimerSeconds').value=duration%60}$('studyTimerStart').disabled=!has;$('studyTimerReset').disabled=!has;$('applyStudyTimerDuration').disabled=!has;if(has)$('studyTimerStart').textContent=state.running?'暂停':value>0?'继续':'开始';$('studyTimerState').textContent=has?(state.running?'正在计时；收起窗口或切换模块后仍会继续。':state.mode==='countdown'&&value===0?'倒计时已结束，可重置或重新设定。':value>0?'已暂停，进度已保存。':'等待开始。'):'请在英语、数学或政治的小任务旁点击“计时”。';$('studyTimerState').classList.toggle('running',!!state?.running);$('timerDockState').textContent=has&&state.running?formatStudyTime(value):'学习计时';$('openStudyTimerPanel').classList.toggle('is-active',!!state?.running);renderStudyTimerButtons()}
function closeStudyTimerPanel(){$('studyTimerPanel').classList.remove('open');$('studyTimerPanel').setAttribute('aria-hidden','true');$('openStudyTimerPanel').setAttribute('aria-expanded','false')}
function showStudyTimerPanel(base,label){setEnglishInkEnabled(false,{quiet:true});closeEnglishInkPanel();closeWordLookup();const key=studyTimerKey(base);activeStudyTimerKey=key;localStorage.setItem('tri-active-study-timer',key);studyTimerRecord(key,label);saveStudyTimers();$('studyTimerPanel').classList.add('open');$('studyTimerPanel').setAttribute('aria-hidden','false');$('openStudyTimerPanel').setAttribute('aria-expanded','true');renderActiveStudyTimer()}
function openActiveStudyTimerPanel(){if(activeStudyTimerKey&&studyTimers[activeStudyTimerKey]){setEnglishInkEnabled(false,{quiet:true});closeEnglishInkPanel();closeWordLookup();$('studyTimerPanel').classList.add('open');$('studyTimerPanel').setAttribute('aria-hidden','false');$('openStudyTimerPanel').setAttribute('aria-expanded','true');return renderActiveStudyTimer()}const view=document.querySelector('.view.active')?.id||'english',subject=SUBJECT_LABELS[view]||'学习';showStudyTimerPanel(`${view}-free-focus`,`${subject} · 自定义学习`)}
function bindStudyTimerButtons(root=document){root.querySelectorAll?.('[data-study-timer-key]').forEach(button=>{if(button.dataset.studyTimerBound)return;button.dataset.studyTimerBound='1';button.addEventListener('click',()=>showStudyTimerPanel(button.dataset.studyTimerKey,button.dataset.studyTimerLabel||'学习任务'))});renderStudyTimerButtons(root)}
function tickStudyTimers(){let completed='';for(const state of Object.values(studyTimers)){if(state?.running&&state.mode==='countdown'&&studyTimerValue(state)<=0){state.baseSeconds=0;state.running=false;state.startedAt=0;state.completedAt=Date.now();completed=state.label}}if(completed){saveStudyTimers();navigator.vibrate?.([160,80,160]);toast(`${completed} · 倒计时完成`)}renderActiveStudyTimer()}
function initStudyTimers(){$('openStudyTimerPanel').onclick=openActiveStudyTimerPanel;$('closeStudyTimerPanel').onclick=closeStudyTimerPanel;document.querySelectorAll('[data-study-timer-mode]').forEach(button=>button.onclick=()=>{const state=activeStudyTimer();if(!state)return;pauseStudyTimer(state);state.mode=button.dataset.studyTimerMode;state.baseSeconds=state.mode==='countdown'?state.durationSeconds:0;saveStudyTimers();renderActiveStudyTimer()});$('applyStudyTimerDuration').onclick=()=>{const state=activeStudyTimer();if(!state)return;const duration=Math.min(359999,Math.max(0,(+$('studyTimerHours').value||0)*3600+(+$('studyTimerMinutes').value||0)*60+(+$('studyTimerSeconds').value||0)));if(!duration)return toast('倒计时至少设置 1 秒');pauseStudyTimer(state);state.mode='countdown';state.durationSeconds=duration;state.baseSeconds=duration;saveStudyTimers();renderActiveStudyTimer();toast('倒计时时长已设定')};$('studyTimerStart').onclick=()=>{const state=activeStudyTimer();if(!state)return;if(state.running)pauseStudyTimer(state);else{Object.entries(studyTimers).forEach(([key,item])=>{if(key!==activeStudyTimerKey)pauseStudyTimer(item)});if(state.mode==='countdown'&&state.baseSeconds<=0)state.baseSeconds=state.durationSeconds;state.running=true;state.startedAt=Date.now()}saveStudyTimers();renderActiveStudyTimer()};$('studyTimerReset').onclick=()=>{const state=activeStudyTimer();if(!state)return;pauseStudyTimer(state);state.baseSeconds=state.mode==='countdown'?state.durationSeconds:0;delete state.completedAt;saveStudyTimers();renderActiveStudyTimer()};bindStudyTimerButtons();renderActiveStudyTimer();studyTimerTickId=setInterval(tickStudyTimers,1000);tickStudyTimers()}
function loadSentenceNotes(){const state=subjectPlanState('english'),daily=englishFor(state.index),suffix=englishRecordSuffix(),legacy=englishLegacyDate(daily.articleIndex);['sentenceOriginal','sentenceCore','sentenceClause','sentenceTranslation'].forEach(id=>{const key='tri-'+id+'-'+suffix,old=localStorage.getItem('tri-'+id+'-'+legacy),value=localStorage.getItem(key);$(id).value=value??old??(id==='sentenceOriginal'?daily.long:'');if(value===null&&old!==null)localStorage.setItem(key,old)})}
['sentenceOriginal','sentenceCore','sentenceClause','sentenceTranslation'].forEach(id=>{$(id).oninput=()=>localStorage.setItem(`tri-${id}-${englishRecordSuffix()}`,$(id).value)});

