function renderHistory(){const logs=read('tri-logs',[]);$('history').innerHTML=logs.length?`<div class="history-row"><b>日期</b><b>均重</b><b>学习</b><b>训练</b><b>引体</b><b>单词</b></div>`+logs.slice().reverse().map(x=>`<div class="history-row"><span>${x.date}</span><span>${x.weight||'—'}kg</span><span>${x.hours||'—'}h</span><span>${x.workouts||'—'}次</span><span>${x.pullups||'—'}次</span><span>${x.words||'—'}个</span></div>`).join(''):`<div class="empty">还没有记录，建议每周日更新一次。</div>`}
$('saveLog').onclick=()=>{if(!$('logDate').value)return toast('请先选择日期');let logs=read('tri-logs',[]),obj={date:$('logDate').value,weight:$('weight').value,hours:$('hours').value,workouts:$('workouts').value,pullups:$('pullups').value,words:$('wordsLearned').value};logs=logs.filter(x=>x.date!==obj.date);logs.push(obj);logs.sort((a,b)=>a.date.localeCompare(b.date));write('tri-logs',logs);renderHistory();toast('周记录已保存')};
function escapeHtml(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}function escapeAttr(s=''){return escapeHtml(s)}
function renderAll(){['math','politics'].forEach(subject=>{if(courseCatalog[subject]?.length)rebuildSmartSchedule(subject)});renderHeader();renderToday();renderSchedule();render365();renderEnglish();renderMath();renderPolitics();renderFitness();renderNutrition();renderFinance();renderHistory()}
function periodTimes(){return studyTiming.starts.flatMap(time=>{const start=StudyPlanner.clock(time);return[{start,end:start+45},{start:start+50,end:start+95}]})}
function studyWindows(){const start=StudyPlanner.clock(studyTiming.wake),end=StudyPlanner.clock(studyTiming.end);return [[start,480],[510,720],[840,1080],[1140,end]].map(([a,b])=>[Math.max(a,start),Math.min(b,end)]).filter(([a,b])=>b>a)}
function dayConstraints(date){
 const week=weekForDate(date),validWeek=week>0&&week<=settings.termWeeks,classes=validWeek?coursesFor(date.getDay(),week):[],periods=periodTimes(),busy=[],warnings=[];
 classes.forEach(course=>{const first=periods[+course.start-1],last=periods[+course.end-1];if(first&&last)busy.push({start:first.start-studyTiming.buffer,end:last.end+studyTiming.buffer,label:course.name,classStart:first.start,classEnd:last.end});else{busy.push({start:0,end:1440,label:course.name});warnings.push(course.name+' 的节次超出已设置作息，请先完善作息再排期。')}});
 const events=validWeek?termEvents.filter(event=>isActive(event,week)):[];
 if(date.getDay()!==0&&date.getDay()!==6){const full=events.filter(event=>/实习|设计/.test(event.name));if(full.length&&studyTiming.practice){busy.push({start:510,end:1080,label:full.map(event=>event.name).join('、')});warnings.push('本周 '+full.map(event=>event.name).join('、')+'：暂预留工作日 08:30–18:00，实际不占白天时可在作息设置取消。')}const extra=events.filter(event=>!/实习|设计/.test(event.name));if(extra.length)warnings.push(extra.map(event=>event.name).join('、')+' 未提供具体时段；遇到集中活动请使用本日顺延。')}
 return {busy,warnings,classes,week};
}
function studyTasksFor(date){
 const key=dateKey(date),tasks=[],states=Object.fromEntries(['english','math','politics'].map(subject=>[subject,subjectPlanState(subject,date)]));
 const add=(subject,title,minutes,focus=false,morning=false)=>tasks.push({subject,title,minutes,focus,morning});
 if(!states.english.postponed){const pos=englishReadingPosition(states.english.index);add('english','到期词复习 + 15 个新词',30,false,true);add('english',pos.review?'同篇闭卷重做与错因复盘':'完整精读与全部阅读问题',40,true);add('english',pos.review?'长难句复述、重译与核对笔记':'长难句拆解与独立翻译',20);add('english','原文生词回收',10)}
 for(const subject of ['math','politics']){
  if(states[subject].postponed)continue;
  const daily=subject==='math'?mathFor(states[subject].index):politicsFor(states[subject].index);
  const weekly=subject==='math'&&dateFromIndex(states[subject].index).getDay()===0;
  const costs=subject==='math'?(weekly?[15,45,40]:[75,30,45]):politicsMode==='light'?[10,10]:politicsMode==='normal'?[20,10,10]:[40,10,10];
  const imported=smartItemsFor(subject,key),backlog=backlogFor(subject,key),items=[...backlog,...imported.filter(item=>!backlog.some(old=>old.id===item.id))];
  const videos=items.filter(item=>item.kind==='video').reduce((n,item)=>n+(item.minutes||45),0),notes=items.filter(item=>item.kind!=='video').reduce((n,item)=>n+(item.minutes||20),0);
  daily.tasks.forEach((task,i)=>add(subject,task[0],Math.max(costs[i],i===0?videos:i===1?notes:0),subject==='math'&&i!==1));
 }
 if(dayConstraints(date).classes.some(course=>course.type==='core'))add('course','核心课程收口与作业归档',20);
 return tasks;
}
function studyScheduleFor(date){const constraints=dayConstraints(date),plan=StudyPlanner.allocate(studyTasksFor(date),studyWindows(),constraints.busy);return {...plan,...constraints}}
function timeSpan(session){return StudyPlanner.label(session.start)+'–'+StudyPlanner.label(session.end)}
function renderStudyTimeline(id,date){
 const box=$(id);if(!box)return;const plan=studyScheduleFor(date),labels={...SUBJECT_LABELS,course:'课程'};
 box.innerHTML='<div class="section-head"><div><div class="eyebrow">STUDY TIME</div><h3>按课表安排的学习时段</h3></div><b>'+plan.scheduled+' / '+plan.total+' 分钟</b></div><p class="muted">每日可学习 '+studyTiming.wake+'–'+studyTiming.end+'；预留三餐、午休、课前后 '+studyTiming.buffer+' 分钟，以及学习块间 5 分钟。可在动态课表中修改作息。</p>'+
 (plan.warnings.length?'<p class="schedule-warning">'+plan.warnings.map(escapeHtml).join('<br>')+'</p>':'')+
 '<div class="time-session-list">'+plan.sessions.map(session=>'<div class="time-session '+session.subject+'"><time>'+timeSpan(session)+'</time><span><b>'+labels[session.subject]+' · '+escapeHtml(session.title)+'</b><small>'+session.minutes+' 分钟'+(session.part>1?' · 续学':'')+'</small></span></div>').join('')+'</div>'+
 (plan.pending.length?'<div class="schedule-warning"><b>空档不足，以下内容保留待安排（未删减）</b><ul>'+plan.pending.map(task=>'<li>'+labels[task.subject]+' · '+escapeHtml(task.title)+'：剩余 '+task.minutes+' 分钟</li>').join('')+'</ul><p>请在对应科目选择“本日顺延”，或调整可学习时段。课程、题目和复盘内容都会保留。</p></div>':'<p class="schedule-complete">今日全部任务已排入空档。</p>');
}
function renderSubjectTime(subject){const box=$(subject+'TimeSlots');if(!box)return;const plan=studyScheduleFor(selectedPlanDate),sessions=plan.sessions.filter(item=>item.subject===subject),pending=plan.pending.filter(item=>item.subject===subject);box.textContent=subjectPlanState(subject).postponed?'今天已顺延，任务与复习顺序保留。':sessions.map(item=>timeSpan(item)+' '+item.title).join('；')+(pending.length?'；待安排 '+pending.reduce((n,item)=>n+item.minutes,0)+' 分钟（任务保留）':'')}
function fillStudyTiming(){studyTiming.starts.forEach((value,i)=>$('classStart'+i).value=value);$('studyWake').value=studyTiming.wake;$('studyEnd').value=studyTiming.end;$('classBuffer').value=studyTiming.buffer;$('reservePractice').checked=studyTiming.practice}
